<x-card title="Trip Rate Directory"><div class="filter-bar"><select id="tr-group"><option value="">All vehicle groups</option>@foreach($vehicleGroups as $x)<option value="{{ $x->vehicle_group_description }}">{{ $x->vehicle_group_description }}</option>@endforeach</select><select id="tr-client"><option value="">All clients</option>@foreach($clients as $x)<option value="{{ $x->client_code }}">{{ $x->client_code }}</option>@endforeach</select><select id="tr-type"><option value="">All delivery types</option>@foreach($tripTypes as $x)<option value="{{ $x->trip_type }}">{{ $x->trip_type }}</option>@endforeach</select><select id="tr-payment"><option value="">All payment types</option>@foreach($payments as $x)<option value="{{ $x->payment_type }}">{{ $x->payment_type }}</option>@endforeach</select><select id="tr-vehicle"><option value="">All vehicle types</option>@foreach($vehicleTypes as $x)<option value="{{ $x->vehicle_type }}">{{ $x->vehicle_type }}</option>@endforeach</select><select id="tr-status"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div class="table-wrap"><table id="trip-rates-table" class="access-table" style="width:100%"><thead><tr><th>Trip No.</th><th>Trip Type</th><th>Payment Type</th><th>Client</th><th>Route</th><th>Vehicle</th><th>Driver Rate</th><th>Status</th><th>Actions</th></tr></thead><tbody></tbody></table></div><div id="trip-rates-fallback-pagination" class="filter-bar" hidden><button id="tr-prev" type="button" class="button button-outline">Previous</button><span id="tr-page">Page 1</span><button id="tr-next" type="button" class="button button-outline">Next</button></div></x-card>
