<script>
document.addEventListener('DOMContentLoaded',function(){var table=document.querySelector('#trip-rates-table'),filters=['group','client','type','payment','vehicle','status'].map(function(x){return document.querySelector('#tr-'+x)}),url=@json(route('trip-rates.index'));
if(typeof window.DataTable==='function'){var dt=new window.DataTable(table,{processing:true,serverSide:true,pageLength:15,lengthMenu:[15,25,50,100],ajax:{url:url,data:function(d){['vehicle_group','client_code','delivery_type','payment_type','vehicle_type','status'].forEach(function(k,i){d[k]=filters[i]&&filters[i].value||''})}},columns:[{data:'trip_number'},{data:'trip_type'},{data:'payment_type'},{data:'client_code'},{data:'route'},{data:'vehicle'},{data:'driver_rate'},{data:'status',orderable:false},{data:'actions',orderable:false}]});filters.forEach(function(f){if(f)f.addEventListener('change',function(){dt.ajax.reload()})});return;}
var page=0,size=15,pager=document.querySelector('#trip-rates-fallback-pagination'),prev=document.querySelector('#tr-prev'),next=document.querySelector('#tr-next'),label=document.querySelector('#tr-page'),body=table.querySelector('tbody');function load(){var p=new URLSearchParams({draw:1,start:page*size,length:size});['vehicle_group','client_code','delivery_type','payment_type','vehicle_type','status'].forEach(function(k,i){p.set(k,filters[i]&&filters[i].value||'')});fetch(url+'?'+p,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}).then(function(r){if(!r.ok)throw new Error('Request failed ('+r.status+').');return r.json()}).then(function(payload){body.innerHTML=payload.data.map(function(row){return '<tr><td>'+row.trip_number+'</td><td>'+row.trip_type+'</td><td>'+row.payment_type+'</td><td>'+row.client_code+'</td><td>'+row.route+'</td><td>'+row.vehicle+'</td><td>'+row.driver_rate+'</td><td>'+row.status+'</td><td>'+row.actions+'</td></tr>'}).join('');pager.hidden=false;label.textContent='Page '+(page+1);prev.disabled=page===0;next.disabled=(page+1)*size>=payload.recordsFiltered}).catch(function(){window.AppNotifications.error('Unable to load trip rates. Please try again.')})}prev.onclick=function(){if(page){page--;load()}};next.onclick=function(){page++;load()};filters.forEach(function(f){if(f)f.onchange=function(){page=0;load()}});load();});
</script>
